package com.soumya.walletwise.finance;
import jakarta.servlet.http.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/transactions") @CrossOrigin(origins="*") public class TransactionController{final TransactionRepository repo;TransactionController(TransactionRepository r){repo=r;}record Input(@NotBlank String type,@NotBlank String category,@Positive BigDecimal amount,String description,LocalDate date){}String uid(HttpServletRequest r){return(String)r.getAttribute("userId");}@GetMapping Page<Transaction> all(HttpServletRequest r,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size,@RequestParam(defaultValue="date")String sort){return repo.findByUserId(uid(r),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,sort)));}@PostMapping @ResponseStatus(HttpStatus.CREATED)Transaction create(HttpServletRequest r,@Valid@RequestBody Input i){if(!Set.of("income","expense").contains(i.type()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"type must be income or expense");Transaction t=new Transaction();t.userId=uid(r);t.type=i.type();t.category=i.category();t.amount=i.amount();t.description=i.description();t.date=i.date()==null?LocalDate.now():i.date();return repo.save(t);}@GetMapping("/{id}")Transaction one(HttpServletRequest r,@PathVariable String id){return find(r,id);}@PutMapping("/{id}")Transaction update(HttpServletRequest r,@PathVariable String id,@Valid@RequestBody Input i){Transaction t=find(r,id);t.type=i.type();t.category=i.category();t.amount=i.amount();t.description=i.description();t.date=i.date()==null?t.date:i.date();return repo.save(t);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(HttpServletRequest r,@PathVariable String id){repo.delete(find(r,id));}Transaction find(HttpServletRequest r,String id){return repo.findByIdAndUserId(id,uid(r)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Transaction not found"));}@GetMapping("/health")Map<String,String> health(){return Map.of("status","UP","service","finance-service");}}
